import SwiftUI
struct RecipeScreen: View {
    let recipeID = 10
    @State private var showsIngredients = false
    var body: some View {
        Toggle("Ингредиенты", isOn: $showsIngredients)
            .sheet(isPresented: $showsIngredients) {
                Text("Ингредиенты рецепта \(recipeID)")
            }
    }
}

sheet привязан к Bool состояния экрана рецепта. После закрытия флаг станет false; основной экран остаётся на месте.

