import SwiftUI
struct LibraryScreen: View {
    @State private var path: [Int] = []
    private let books = [3: "Север"]
    var body: some View {
        NavigationStack(path: $path) {
            NavigationLink("Книга", value: 9)
                .navigationDestination(for: Int.self) { bookID in
                    VStack {
                        Text(books[bookID] ?? "Книга удалена")
                        Button("Библиотека") { path.removeAll() }
                    }
                }
        }
    }
}
